WITH UserActivity AS (SELECT U.Id AS UserId, U.DisplayName, COALESCE(SUM(P.ViewCount), 0) AS TotalViews, COALESCE(SUM(P.Score), 0) AS TotalScore, COUNT(DISTINCT P.Id) AS TotalPosts, COUNT(DISTINCT C.Id) AS TotalComments FROM Users AS U LEFT JOIN Posts AS P ON U.Id = P.OwnerUserId LEFT JOIN Comments AS C ON P.Id = C.PostId WHERE U.Reputation > 100 GROUP BY U.Id, U.DisplayName), RankedUsers AS (SELECT UserId, DisplayName, TotalViews, TotalScore, TotalPosts, TotalComments, ROW_NUMBER() OVER (ORDER BY TotalScore DESC NULLS FIRST) AS ScoreRank, ROW_NUMBER() OVER (ORDER BY TotalViews DESC NULLS FIRST) AS ViewsRank FROM UserActivity), UserBadges AS (SELECT B.UserId, GROUP_CONCAT(B.Name, ', ') AS BadgeNames, COUNT(B.Id) AS BadgeCount FROM Badges AS B GROUP BY B.UserId) SELECT RU.DisplayName, RU.TotalPosts, RU.TotalViews, RU.TotalScore, UB.BadgeNames, UB.BadgeCount, CASE WHEN RU.ScoreRank <= 10 THEN 'Top User' ELSE 'Regular User' END AS UserCategory FROM RankedUsers AS RU LEFT JOIN UserBadges AS UB ON RU.UserId = UB.UserId WHERE (UB.BadgeCount IS NULL OR UB.BadgeCount > 0) AND RU.TotalPosts > 5 ORDER BY RU.TotalScore DESC NULLS FIRST, RU.TotalViews DESC NULLS FIRST LIMIT 20